head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vSelectYear = "";
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        await scwin.searchCode();
        await scwin.grdSearchCode();
        const firstYear = dts_BAS_YY.getCellData(1, "VALUE");
        cmb_BAS_YY.setValue(firstYear);
        scwin.vSelectYear = firstYear;
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07405.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search1_onclick
 * @description btn_Search1 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search1_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07405.btn_Search1_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07405.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07405.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnFail = function() {
    try {
        $c.lc.fn_alertMsg('F');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07405.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        await scwin.searchCode();
        if (scwin.vSelectYear === undefined && dts_BAS_YY.getRowCount() > 0) {
            cmb_BAS_YY.setValue(dts_BAS_YY.getCellData(1, "VALUE"));
        }
        cmb_BAS_YY.setValue(scwin.vSelectYear);
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07405.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_Modify_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Modify_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07405.btn_Modify_onclick" });
    }
};

/**
 * @method
 * @name btn_Delete_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Delete_onclick = function() {
    try {
        dts_List.removeRow(dts_List.getRowPosition());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07405.btn_Delete_onclick" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_New_onclick = function() {
    try {
        dts_List.insertRow();
        const year = cmb_BAS_YY.getValue();
        if (year !== "") {
            dts_List.setCellData(dts_List.getRowPosition(), "BAS_YY", year);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07405.btn_New_onclick" });
    }
};

/**
 * @method
 * @name grd_Grid_OnPopup
 * @description grd Grid On Popup 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @param {*} data 데이터
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnPopup = async function(row, colid, data) {
    try {
        // fn_SetPar = fn_SetInstPtnt2;
        const wth = 1400;
        const hgt = 830;
        const pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
        const options = {
            id: "ULDSTF07400",
            title: "전문평가관리내역",
            type: "browserPopup",
            width: wth,
            height: hgt,
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("ULDSTF07400.gfm", options);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07405.grd_Grid_OnPopup" });
    }
};

/**
 * @method
 * @name cmb_BAS_YY_onselchange
 * @description cmb_BAS_YY onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_BAS_YY_onselchange = async function() {
    try {
        scwin.vSelectYear = cmb_BAS_YY.getValue();
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07405.cmb_BAS_YY_onselchange" });
    }
};

/**
 * @method
 * @name MaxTab_01_OnSelChanged
 * @description Max Tab 01 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MaxTab_01_OnSelChanged = async function(nIndex) {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07405.MaxTab_01_OnSelChanged" });
    }
};

/**
 * @method
 * @name dts_List2_OnLoadCompleted
 * @description dts_List2 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List2_OnLoadCompleted = async function(rowcount) {
    try {
        await scwin.setGrid();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07405.dts_List2_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List3_OnLoadCompleted
 * @description dts_List3 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List3_OnLoadCompleted = function(rowcount) {
    try {
        scwin.setGrid2();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07405.dts_List3_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Excel_onclick = async function() {
    try {
        if (dts_List3.getRowCount() > 0) {
            // 엑셀 로그
            $c.stf.doLogSave("ULDSTF07405.xml", SCREN_PROCS_TP_CD_07);
            $c.data.downloadGridViewOffice(grd_List, "TCB별 배정내역", "", 8, 0);
        } else {
            await $c.win.alert(NO_EXCEL_DATA);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07405.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name image_2_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.image_2_onclick = async function() {
    try {
        if (dts_List.getRowCount() > 0) {
            // 엑셀 로그
            $c.stf.doLogSave("ULDSTF07405.xml", SCREN_PROCS_TP_CD_07);
            $c.data.downloadGridViewOffice(grd_Grid, "TCB별 배정내역 입력", "", 8, 0);
        } else {
            await $c.win.alert(NO_EXCEL_DATA);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07405.image_2_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchCode
 * @description 콤보박스 값 설정
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_BAS_YY",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_BAS_YY=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "";
    for (j = 1; j <= dts_BAS_YY.getRowCount(); j++) {
        strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_BAS_YY.getCellData(j, "VALUE") + "^" + dts_BAS_YY.getCellData(j, "TEXT");
    }
    cmb_BAS_YY.CBData = strCbd;
};

/**
 * @method
 * @name grdSearchCode
 * @description grd Search Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grdSearchCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    strCbdReason = "' ':"; // 초기값

    for (k = 1; k <= dts_Cod.getRowCount(); k++) {
        if (dts_Cod.getCellData(k, "CD_ENG_NM") === "SPECY_VALU_INST_CD") {
            strCbdReason = strCbdReason + (strCbdReason === "" ? "" : ",") + dts_Cod.getCellData(k, "VALUE") + ":" + dts_Cod.getCellData(k, "TEXT");
        }
    }
    $c.cm.setColumnProp(grd_Grid, 'SPECY_VALU_INST_CD', 'Data', strCbdReason);
};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        url += "&BAS_YY=" + cmb_BAS_YY.getValue(); // 연도

        const sbmOptions = {
            id : "sbm_dts_List",
            action : "/lstinvstg/KsqSkilValu.do",
            ref : "",
            target : "dts_List=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else {
        url += "&BAS_YY=" + cmb_BAS_YY.getValue(); // 연도

        const sbmOptions = {
            id : "sbm_dts_List2",
            action : "/lstinvstg/KsqSkilValu.do",
            ref : "",
            target : "dts_List2=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function() {
    if (TR_JOB === "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    }
    trs_Save.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/lstinvstg/KsqSkilValu.do",
        ref : "dts_List",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name setGrid
 * @description set Grid 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setGrid = async function() {
    if (dts_List2.getRowCount() > 0) {
        const sbmOptions = {
            id : "sbm_dts_List3",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_List3=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    TR_JOB = 'I';
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(TR_JOB)) return;
        await scwin.trs(TR_JOB_INSERT);
    }
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    for (let i = 1, j = dts_List.getRowCount(); i <= j; i++) {
        const status = dts_List.getRowStatus(i);
        if (status === 1 || status === 3) {
            if (dts_List.getCellData(i, "SPECY_VALU_INST_CD") === " ") {
                await $c.win.alert(i + "번째행  " + "TCB기관명은 필수값입니다.");
                return false;
            }
            if (dts_List.getCellData(i, "BAS_YY") === "") {
                await $c.win.alert(i + "번째행  " + "연도는 필수값입니다.");
                return false;
            }
            if (dts_List.getCellData(i, "SORT_ORD") === "") {
                await $c.win.alert(i + "번째행  " + "배정순번은 필수값입니다.");
                return false;
            }
            if (dts_List.getCellData(i, "COL_ORD_SEQ") === "") {
                await $c.win.alert(i + "번째행  " + "컬럼순번은 필수값입니다.");
                return false;
            }
            let instCd, rowOrd, colOrd, basYy, instNm;
            let instCdIn, rowOrdIn, colOrdIn, instNmIn, basYyIn;
            instCd = dts_List.getCellData(i, "SPECY_VALU_INST_CD");
            rowOrd = dts_List.getCellData(i, "SORT_ORD");
            colOrd = dts_List.getCellData(i, "COL_ORD_SEQ");
            basYy = dts_List.getCellData(i, "BAS_YY");
            instNm = dts_Cod.getCellData($c.cp.getNameValueRow(dts_Cod, "VALUE", instCd), "TEXT");
            for (let k = 1, l = dts_List.getRowCount(); k <= l; k++) {
                if (i === k) continue;
                instCdIn = dts_List.getCellData(k, "SPECY_VALU_INST_CD");
                rowOrdIn = dts_List.getCellData(k, "SORT_ORD");
                colOrdIn = dts_List.getCellData(k, "COL_ORD_SEQ");
                instNmIn = dts_Cod.getCellData($c.cp.getNameValueRow(dts_Cod, "VALUE", instCdIn), "TEXT");
                basYyIn = dts_List.getCellData(k, "BAS_YY");
                if (instCd === instCdIn && basYy === basYyIn) {
                    if (rowOrd === rowOrdIn) {
                        await $c.win.alert("'" + instNmIn + "' 중복된 배정순번이 존재합니다.");
                        return false;
                    }
                    if (colOrd !== colOrdIn) {
                        await $c.win.alert("'" + instNmIn + "' 컬럼순번이 다른값이 존재합니다.");
                        return false;
                    }
                }
                if (instCd !== instCdIn && basYy === basYyIn) {
                    if (colOrd === colOrdIn) {
                        await $c.win.alert("TCB기관별(" + instNm + " ," + instNmIn + ")중복된 컬럼순번이 존재합니다.");
                        return false;
                    }
                }
            }
        }
    }
    return true;
};

/**
 * @method
 * @name setGrid2
 * @description set Grid2 처리
 * @returns {void}
 * @hidden N
 */
scwin.setGrid2 = function() {
    for (let i = 1, j = 12; i <= j; i++) {
        $c.cm.setColumnProp(grd_List, "COM_NM" + i, "Name", "배정회사" + i);
    }
    const maxRow = $c.cp.nameMax(dts_List2, "SORT_ORD", 0, 0);
    const maxCol = $c.cp.nameMax(dts_List2, "COL_ORD_SEQ", 0, 0);
    dts_List3.setBroadcast(false);
    for (let i = 1, j = maxRow; i <= j; i++) {
        dts_List3.insertRow();
    }
    dts_List3.setBroadcast(true, true);
    for (let i = 1, j = 12; i <= j; i++) {
        if (i <= maxCol) {
            $c.cm.setColumnProp(grd_List, "COM_NM" + i, "Show", true);
        } else {
            $c.cm.setColumnProp(grd_List, "COM_NM" + i, "Show", false);
        }
    }
    dts_List3.setBroadcast(false);
    for (let k = 1, l = maxCol; k <= l; k++) {
        for (let i = 1, j = maxRow; i <= j; i++) {
            const findRow = $c.cp.getNameValueRow(dts_List2, "MAKED_KEY", i + "_" + k);
            if (findRow > 0) {
                dts_List3.setCellData(i, "COM_NM" + k, dts_List2.getCellData(findRow, "ASSGN_COM_NM"));
                let grdHeadName = $c.cm.getColumnProp(grd_List, "COM_NM" + k, "Name");
                $c.cm.setColumnProp(grd_List, "COM_NM" + k, "Name", dts_List2.getCellData(findRow, "SKIL_VALU_INST_CD_NM"));
            }
        }
    }
    dts_List3.setBroadcast(true, true);
    for (let i = 1, j = 12; i <= j; i++) {
        let grdHeadName = $c.cm.getColumnProp(grd_List, "COM_NM" + i, "Name");
        if (grdHeadName.indexOf("배정회사") > -1) {
            $c.cm.setColumnProp(grd_List, "COM_NM" + i, "Show", false);
        }
    }
    $c.stf.fillGridHeaderTotalCnt(maxRow, panel_page);
};
